using System.Collections.Generic;
using UnityEngine;
namespace NakiLegend.Prototype {
 public sealed partial class NakiPrototype {
  private sealed class FireBomb {public Vector2 at;public float when,radius;public GameObject root;}
  private readonly List<FireBomb> fireBombs=new List<FireBomb>();
  private static bool IsFireEnemy(EnemyKind kind){return kind>=EnemyKind.AshRaider&&kind<=EnemyKind.AshPackbeast;}
  private void ConfigureFireEnemy(Enemy e){if(IsCoreEnemy(e.kind)){ConfigureCoreEnemy(e);return;}if(IsWorkshopEnemy(e.kind)){ConfigureWorkshopEnemy(e);return;}e.boss=e.kind==EnemyKind.RedSpineLizard;e.radius=e.boss?.9f:e.kind==EnemyKind.EmberLizard?.4f:.32f;e.hp=e.maximum=e.boss?1080:e.kind==EnemyKind.EmberLizard?110:e.kind==EnemyKind.AshRaider?96:e.kind==EnemyKind.AshBat?72:84;e.speed=e.boss?1.3f:e.kind==EnemyKind.AshBat?1.8f:1.35f;e.affinity=e.attackElement=Element.Fire;e.iceArmor=e.boss?3:e.kind==EnemyKind.EmberLizard?1:0;e.soulEligible=true;e.nextAttack=clock+1.4f;}
  private void CrackFireShell(Enemy e,bool ice){e.iceArmor--;e.poise=0;SpellSpark(e.position,ice?C("c4f2ff"):C("ffc28a"),.6f);if(e.iceArmor==0){e.windup=e.chargeUntil=0;if(e.warning!=null)Destroy(e.warning);e.recoveryUntil=clock+1.3f;e.nextAttack=clock+1.5f;AddFloatingHit(ice?"熔壳冷裂 · 反击窗口":"熔壳破裂 · 反击窗口",e.position+Vector2.up*1.5f,C("b2f2ff"));}}
  private float FireShellDamage(Enemy e,float amount,Element element){if(!IsFireEnemy(e.kind)||e.iceArmor<=0||RecoveryWindow(e))return amount;if(element==Element.Ice){e.iceSlowUntil=clock+(e.boss?.8f:1.5f);CrackFireShell(e,true);return e.iceArmor==0?amount:amount*.85f;}e.poise+=amount;if(e.poise>=(e.boss?60:35))CrackFireShell(e,false);return amount*.7f;}
  private void UpdateFireEnemy(Enemy e,float dt){if(IsCoreEnemy(e.kind)){UpdateCoreEnemy(e,dt);return;}if(IsWorkshopEnemy(e.kind)){UpdateWorkshopEnemy(e,dt);return;}RecoverIceFooting(e);Vector2 old=e.position,to=position-e.position;float slow=clock<e.iceSlowUntil?(e.boss?.8f:.5f):1;
   if(e.boss&&!e.secondPhase&&e.hp<e.maximum*.7f){e.secondPhase=true;e.iceArmor=2;e.windup=e.chargeUntil=0;if(e.warning!=null)Destroy(e.warning);e.recoveryUntil=clock+1.2f;e.nextAttack=clock+1.5f;AddFloatingHit("赤脊升温 · 警惕连续火团",e.position+Vector2.up*2,C("ffc886"));}
   if(e.chargeUntil>0){if(clock<e.chargeUntil){Vector2 next=MoveEnemyCharge(e,e.attackDirection*(e.boss?6.5f:5.5f)*slow*dt);if(IceNavigationLine(e.position,next,e.radius))e.position=next;else e.chargeUntil=clock;if(DistanceToSegment(position,old,e.position)<e.radius+.3f&&!ProjectilePathBlocked(e.position,position,.04f))TakeJourneyDamage(e.boss?2:1,Element.Fire);}else{e.chargeUntil=0;e.recoveryUntil=clock+.9f;}}
   else if(e.windup>0){e.windup-=dt;if(e.windup<=0){if(e.warning!=null)Destroy(e.warning);ResolveFireMove(e);}}
   else if(clock>=e.recoveryUntil){bool visible=!ProjectilePathBlocked(e.position,position,.14f);float range=e.boss?10:e.kind==EnemyKind.AshRaider?2:e.kind==EnemyKind.AshBat?4:7;if(clock>=e.nextAttack&&visible&&to.magnitude<range){e.attackNumber++;e.attackDirection=to.sqrMagnitude>.01f?to.normalized:Vector2.down;e.strikePoint=position;e.windup=e.boss?1.05f:.8f;e.nextAttack=clock+e.windup+(e.boss?(e.secondPhase?.8f:1.1f):1.45f);e.warning=FireWarning(e);}else if(!visible||to.magnitude>(e.boss?3:e.kind==EnemyKind.AshRaider?1.2f:4))MoveIcePursuit(e,e.speed*slow*dt);}
   e.velocity=dt>0?(e.position-old)/dt:Vector2.zero;e.root.transform.position=e.position+Vector2.up*(e.kind==EnemyKind.AshBat?.25f+.06f*Mathf.Sin(clock*7):e.velocity.sqrMagnitude>.01f?.025f*Mathf.Sin(clock*12):0);e.body.flipX=(e.windup>0?e.attackDirection:to).x<0;e.body.sortingOrder=DepthAt(e.position.y);e.body.color=clock<e.hurtUntil?C("ffe2ba"):e.iceArmor>0?C("ffd3a5"):clock<e.iceSlowUntil?C("b9eaff"):Color.white;if(e.shadow!=null)e.shadow.transform.position=e.position;
  }
  private GameObject FireWarning(Enemy e){int move=e.attackNumber%3;if(e.kind==EnemyKind.CoalThrower||e.boss&&move==0)return WarningCircle(e.strikePoint,e.boss?1.1f:.8f);if(e.kind==EnemyKind.AshRaider||e.kind==EnemyKind.AshBat||e.boss&&move==1)return ChapterLineWarning(e.position,e.attackDirection,e.boss?5:2.5f,e.boss?1.6f:.65f);var root=new GameObject("Locked fire fan warning");root.transform.SetParent(world,false);int count=e.boss?(e.secondPhase?13:9):3;float spacing=e.boss?16:17;DensifyFan(ref count,ref spacing);for(int i=0;i<count;i++){Vector2 d=Quaternion.Euler(0,0,(i-(count-1)*.5f)*spacing)*e.attackDirection;var line=ChapterLineWarning(e.position,d,5,.04f);line.transform.SetParent(root.transform,true);}return root;}
  private void FireFan(Enemy e,int count,float spacing,float speed){if(fireChapterMode&&journeyRooms[currentRoom].stage==2&&!e.boss){float span=(count-1)*spacing;count+=1;spacing=span/(count-1);}DensifyFan(ref count,ref spacing);for(int i=0;i<count;i++){Vector2 d=Quaternion.Euler(0,0,(i-(count-1)*.5f)*spacing)*e.attackDirection;int before=shots.Count;SpawnShot(e.position+d*(e.radius+.2f),d,true,null,e.position);if(shots.Count>before){var s=shots[shots.Count-1];s.emitter=e;s.element=Element.Fire;s.damage=e.boss?1.5f:1;s.speed=speed;s.life=3;s.root.GetComponent<SpriteRenderer>().color=C("ffae65");}}}
  private void ResolveFireMove(Enemy e){e.recoveryUntil=clock+(e.boss?.85f:.6f);if(e.kind==EnemyKind.AshRaider){if(DistanceToSegment(position,e.position,e.position+e.attackDirection*2)<.6f&&!ProjectilePathBlocked(e.position,position,.04f))TakeJourneyDamage(1,Element.Fire);return;}if(e.kind==EnemyKind.AshBat){e.chargeUntil=clock+.4f;return;}if(e.kind==EnemyKind.CoalThrower){QueueFireBomb(e.strikePoint,.9f,.8f);return;}if(!e.boss){FireFan(e,3,17,4.2f);return;}int move=e.attackNumber%3;if(move==1){e.chargeUntil=clock+.6f;FireFan(e,e.secondPhase?5:3,20,3.5f);}else if(move==2)FireFan(e,e.secondPhase?13:9,16,e.secondPhase?4.8f:4.2f);else{QueueFireBomb(e.strikePoint,.8f,1.1f);if(e.secondPhase){QueueFireBomb(FindFreeInteractionPoint(e.strikePoint+Vector2.left*1.8f),1.15f,.8f);QueueFireBomb(FindFreeInteractionPoint(e.strikePoint+Vector2.right*1.8f),1.5f,.8f);}}}
  private void QueueFireBomb(Vector2 at,float delay,float radius){if(fireBombs.Count>=3)return;var warning=WarningCircle(at,radius);Draw("Coal charge",disc,at,Vector2.one*.25f,C("e48c46"),DepthAt(at.y)).transform.SetParent(warning.transform,true);fireBombs.Add(new FireBomb{at=at,when=clock+delay,radius=radius,root=warning});}
  private void ClearFireHazards(){ClearCoreBursts();ClearWorkshopEffects();foreach(var bomb in fireBombs)if(bomb.root!=null)Destroy(bomb.root);fireBombs.Clear();}
  private bool DisarmFireBomb(Vector2 from,Vector2 to,float width){for(int i=fireBombs.Count-1;i>=0;i--){var b=fireBombs[i];if(DistanceToSegment(b.at,from,to)>width+.2f||ProjectilePathBlocked(from,b.at,.02f))continue;if(b.root!=null)Destroy(b.root);fireBombs.RemoveAt(i);SpellSpark(b.at,C("ffdf9b"),.3f);return true;}return false;}
  private void TickFireCombat(){TickCoreBursts();TickWorkshopEffects();for(int i=fireBombs.Count-1;i>=0;i--){var b=fireBombs[i];if(clock<b.when)continue;if(b.root!=null)Destroy(b.root);fireBombs.RemoveAt(i);SpellSpark(b.at,C("ffba6e"),b.radius);SkillSound("meteor","hit");if(Vector2.Distance(position,b.at)<b.radius+.25f&&!ProjectilePathBlocked(b.at,position,.04f))TakeJourneyDamage(1.5f,Element.Fire);}
   foreach(Enemy e in new List<Enemy>(enemies))if(e.hp>0&&clock<e.burnUntil&&clock>=e.nextBurn){e.nextBurn=clock+.5f;SpellSpark(e.position,C("f7b968"),.12f);DamageEnemy(e,SkillDamage(3));}
  }
  private void CastFireBolt(){CastFireVolley();}
 }
}
